def _no_cache(resp):
    resp.headers["Cache-Control"] = "no-store, no-cache, must-revalidate, max-age=0"
    resp.headers["Pragma"] = "no-cache"
    resp.headers["Expires"] = "0"
    return resp


def create_app(manager: ServiceManager, quest_service: QuestService) -> Flask:
    app = Flask(__name__)

    # ── error handlers ────────────────────────────────────

    @app.errorhandler(ServiceNotFound)
    def handle_not_found(exc):
        return jsonify({"error": str(exc)}), 404

    @app.errorhandler(ServiceExistsError)
    def handle_exists(exc):
        return jsonify({"error": str(exc)}), 409

    @app.errorhandler(ServiceAlreadyRunning)
    def handle_already_running(exc):
        return jsonify({"error": str(exc)}), 409

    @app.errorhandler(ServiceAlreadyStopped)
    def handle_already_stopped(exc):
        return jsonify({"error": str(exc)}), 409

    @app.errorhandler(ServiceLifetimeNotManaged)
    def handle_not_managed(exc):
        return jsonify({"error": str(exc)}), 409

    @app.errorhandler(LogNotFound)
    def handle_log_not_found(exc):
        return jsonify({"error": str(exc)}), 404

    @app.errorhandler(TraceRegistrationRequired)
    def handle_trace_registration_required(exc):
        return jsonify({"error": str(exc)}), 400

    @app.errorhandler(RepoNotFound)
    def handle_repo_not_found(exc):
        return jsonify({"error": str(exc)}), 404

    @app.errorhandler(NotAGitRepo)
    def handle_not_git_repo(exc):
        return jsonify({"error": str(exc)}), 422

    @app.errorhandler(InvalidQuestInput)
    def handle_invalid_quest_input(exc):
        return jsonify({"error": str(exc)}), 400

    @app.errorhandler(QuestLockContention)
    def handle_lock_contention(exc):
        return jsonify({
            "error": str(exc),
            "repo_path": exc.repo_path,
            "lock_owner": {
                "quest_type": exc.lock_info.quest_type,
                "quest_number": exc.lock_info.quest_number,
                "request_id": exc.lock_info.request_id,
            },
        }), 409

    @app.errorhandler(QuestNotFound)
    def handle_quest_not_found(exc):
        return jsonify({"error": str(exc)}), 404

    @app.errorhandler(FatalInvariantError)
    def handle_fatal_invariant(exc):
        return jsonify({"error": str(exc)}), 500

    @app.errorhandler(MissingDefaultExecutionConfig)
    def handle_missing_default_execution_config(exc):
        return jsonify({"error": str(exc)}), 500

    @app.errorhandler(HarnessNotAvailable)
    def handle_harness_not_available(exc):
        return jsonify({"error": str(exc)}), 503

    @app.errorhandler(QuestStateParseError)
    def handle_quest_state_parse_error(exc):
        return jsonify({"error": str(exc)}), 422

    @app.errorhandler(dashboard_data.DashboardBadRequest)
    def handle_dashboard_bad_request(exc):
        body: dict = {"error": exc.message}
        if exc.fields:
            body["fields"] = exc.fields
        return jsonify(body), 400

    @app.errorhandler(dashboard_data.DashboardNotFound)
    def handle_dashboard_not_found(exc):
        return jsonify({"error": exc.message}), 404

    # ── routes ────────────────────────────────────────────

    @app.route("/health", methods=["GET"])
    def health():
        return jsonify({
            "status": "ok",
            "uptime_seconds": int(time.time() - manager.started_at),
            "service_count": manager.db.service_count(),
        })

    @app.route("/services", methods=["GET"])
    def get_services():
        name = request.args.get("name")
        return jsonify({
            "services": manager.list_managed_services(name=name)
        })

    @app.route("/register_service", methods=["POST"])
    def register_service():
        data = request.get_json(force=True)
        required = ["name", "url", "log_dir", "start_command", "stop_command"]
        missing = [f for f in required if f not in data]
        if missing:
            return jsonify({"error": f"Missing required fields: {missing}"}), 400

        row, was_replaced = manager.register(
            name=data["name"],
            url=data["url"],
            log_dir=data["log_dir"],
            start_command=data["start_command"],
            stop_command=data["stop_command"],
            git_repo=data.get("git_repo"),
            dont_manage_lifetime=data.get("dont_manage_lifetime", False),
            replace=data.get("replace", False),
        )
        status_code = 200 if was_replaced else 201
        return jsonify({
            "name": row["name"],
            "replaced": was_replaced,
            "registered_at": row["registered_at"],
        }), status_code

    @app.route("/start_service", methods=["POST"])
    def start_service():
        data = request.get_json(force=True)
        name = data.get("name")
        if not name:
            return jsonify({"error": "Missing required field: name"}), 400
        result = manager.start(name)
        return jsonify(result)

    @app.route("/stop_service", methods=["POST"])
    def stop_service():
        data = request.get_json(force=True)
        name = data.get("name")
        if not name:
            return jsonify({"error": "Missing required field: name"}), 400
        result = manager.stop(name)
        return jsonify(result)

    @app.route("/restart_service", methods=["POST"])
    def restart_service():
        data = request.get_json(force=True)
        name = data.get("name")
        if not name:
            return jsonify({"error": "Missing required field: name"}), 400
        result = manager.restart(name)
        return jsonify(result)

    @app.route("/start_all_services", methods=["POST"])
    def start_all_services():
        result = manager.start_all()
        return jsonify(result)

    @app.route("/stop_all_services", methods=["POST"])
    def stop_all_services():
        result = manager.stop_all()
        return jsonify(result)

    @app.route("/all_health", methods=["GET"])
    def all_health():
        services_health = manager.check_all_health()
        return jsonify({
            "conductor": "ok",
            "services": services_health,
        })

    @app.route("/logs", methods=["GET"])
    def logs():
        name = request.args.get("name")
        if not name:
            return jsonify({"error": "Missing required query param: name"}), 400
        tail = request.args.get("tail", "100")
        try:
            tail = int(tail)
            if tail <= 0:
                raise ValueError()
        except ValueError:
            return jsonify({"error": "tail must be a positive integer"}), 400
        file = request.args.get("file")
        result = manager.tail_logs(name, tail=tail, file=file)
        return jsonify(result)

    @app.route("/trace", methods=["POST"])
    def post_trace():
        data = request.get_json(force=True)
        name = data.get("name")
        if not name:
            return jsonify({"error": "Missing required field: name"}), 400

        payload = data.get("payload")
        if payload is None:
            payload = {
                key: value
                for key, value in data.items()
                if key not in {"name", "trace_dir"}
            }
        if not isinstance(payload, dict):
            return jsonify({"error": "payload must be a JSON object"}), 400

        result = manager.append_trace(
            name=name,
            payload=payload,
            trace_dir=data.get("trace_dir"),
        )
        return jsonify(result), 201

